import { matchUploads } from './match.mjs'
import fs from 'fs'

const dir = 'C:/Users/SIFAHI~1/AppData/Local/Temp/opencode/scrape'
const load = (name) => JSON.parse(fs.readFileSync(`${dir}/${name}.json`, 'utf8'))

const owned = {
  MindCipher: load('my-MindCipher'),
  NeuralVault: load('my-NeuralVault'),
  PsycheNoir: load('my-PsycheNoir'),
  DisciplineDoctrine: load('my-DisciplineDoctrine'),
}
const sources = {
  MindCipher: { meta: load('src-ApexMind'), label: 'Apex Mind', link: 'https://www.youtube.com/@ApexMindOffcial' },
  NeuralVault: { meta: load('src-HiddenMind'), label: 'Hidden Mind', link: 'https://www.youtube.com/@realhiddenmindco' },
  PsycheNoir: { meta: load('src-NARCEO'), label: 'NARCEO', link: 'https://www.youtube.com/@narceo05' },
}

// Upload detection runs against ALL owned channels (the app's model: a video can be
// live on several channels; cross-posting still counts as covered).
const uploads = Object.entries(owned).flatMap(([ch, d]) =>
  d.entries.map((e) => ({ channelId: ch, title: e.title })))

const report = {}
for (const [ch, { meta, label, link }] of Object.entries(sources)) {
  const items = meta.entries.map((e) => ({ videoId: e.id, title: e.title }))
  const matches = matchUploads(items, uploads) // app defaults: 0.82 high / 0.6 floor
  const byId = new Map(matches.map((m) => [m.videoId, m]))
  const entries = meta.entries.map((e, i) => {
    const m = byId.get(e.id)
    return {
      id: e.id,
      title: e.title,
      views: e.view_count ?? null,
      duration: e.duration ?? null,
      recencyRank: i, // /videos tab = newest first
      covered: m ? m.uploadedTo : null,
      score: m ? Math.round(m.score * 100) / 100 : null,
      confidence: m ? m.confidence : null,
    }
  })
  const uncovered = entries.filter((e) => !e.covered)
  const suggestion = uncovered[0] || null
  const popular = uncovered.length
    ? uncovered.reduce((a, b) => ((b.views || 0) > (a.views || 0) ? b : a))
    : null
  report[ch] = {
    source: label,
    sourceLink: link,
    myUploads: owned[ch].entries.length,
    sourceVideos: entries.length,
    coveredHigh: entries.filter((e) => e.confidence === 'high').length,
    coveredPending: entries.filter((e) => e.confidence === 'pending').length,
    uncoveredCount: uncovered.length,
    suggestion,
    popularAlternative: popular,
    uncoveredNext: uncovered.slice(1, 6),
  }
}

fs.writeFileSync('C:/Users/SIFAHI~1/AppData/Local/Temp/opencode/suggestions.json', JSON.stringify(report, null, 2))
console.log(JSON.stringify(report, null, 2))

