"""Change Mental Empire Studio channel<->source mappings in the app SQLite DB.

Implements the app's own write semantics (electron/db/index.ts):
- writeSourceOwner(): source_channels.linkedMyChannelId is the authoritative edge;
  my_channels.linkedSourceId/source is the primary-source cache, resynced for BOTH the
  channel that gained and the one that lost a source.
- setChannelSource(): releases the channel's other sources + resets mapDone/mapTotal
  (only the 'sole source' connect flow in the app does this; plain link does not).

Default is a dry-run; pass --apply to write. All changes run in one transaction.
"""

import argparse
import os
import sqlite3
import sys
from datetime import datetime, timezone
from pathlib import Path

LIVE_DIR = "Mental Empire Studio"       # app.setName() in electron/main.ts
LEGACY_DIR = "mental-empire-studio"     # pre-productName builds; stale on this machine
DB_NAME = "mental-empire.db"


def find_db(explicit):
    if explicit:
        p = Path(explicit)
        if not p.exists():
            sys.exit(f"error: --db path does not exist: {p}")
        return p
    appdata = os.environ.get("APPDATA")
    if not appdata:
        sys.exit("error: APPDATA is unset; pass --db explicitly.")
    live = Path(appdata) / LIVE_DIR / DB_NAME
    legacy = Path(appdata) / LEGACY_DIR / DB_NAME
    if live.exists():
        if legacy.exists():
            print(f"note: legacy profile also exists (do not write there): {legacy}")
        return live
    if legacy.exists():
        print("warning: live profile not found; using LEGACY profile (verify this is intended)")
        return legacy
    sys.exit(f"error: no {DB_NAME} under {appdata}\\{LIVE_DIR} or {appdata}\\{LEGACY_DIR}")


def now_iso():
    return datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


class Mapping:
    def __init__(self, db_path):
        self.path = db_path
        self.con = sqlite3.connect(db_path)
        self.cur = self.con.cursor()

    # ---- reads ----
    def my_channel(self, cid):
        return self.cur.execute(
            "SELECT id, name, handle, linkedSourceId FROM my_channels WHERE id=?", (cid,)
        ).fetchone()

    def source(self, sid):
        return self.cur.execute(
            "SELECT id, url, handle, name, avatar, nicheId, linkedMyChannelId FROM source_channels WHERE id=?",
            (sid,),
        ).fetchone()

    def sources_for_channel(self, cid):
        """Both directions, like the export tool: edge OR cache resolves."""
        rows = self.cur.execute(
            "SELECT id, handle FROM source_channels WHERE linkedMyChannelId=?", (cid,)
        ).fetchall()
        cached = self.cur.execute(
            "SELECT linkedSourceId FROM my_channels WHERE id=?", (cid,)
        ).fetchone()
        ids = {r[0] for r in rows}
        if cached and cached[0]:
            ids.add(cached[0])
        if not ids:
            return []
        q = ",".join("?" * len(ids))
        return self.cur.execute(
            f"SELECT id, handle, linkedMyChannelId FROM source_channels WHERE id IN ({q})",
            tuple(ids),
        ).fetchall()

    def cache_primary(self, cid):
        """syncMyChannelSourceCache(): first source by handle/name/url order."""
        return self.cur.execute(
            "SELECT id, handle FROM source_channels WHERE linkedMyChannelId=? "
            "ORDER BY COALESCE(NULLIF(handle,''),name,url) LIMIT 1",
            (cid,),
        ).fetchone()

    # ---- writes (inside a transaction) ----
    def write_owner(self, sid, cid):
        """writeSourceOwner(): set edge, then resync cache on prev + new owner."""
        prev = self.source(sid)[6]
        self.cur.execute("UPDATE source_channels SET linkedMyChannelId=? WHERE id=?", (cid, sid))
        if prev and prev != cid:
            self.sync_cache(prev)
        if cid:
            self.sync_cache(cid)

    def sync_cache(self, cid):
        primary = self.cache_primary(cid)
        self.cur.execute(
            "UPDATE my_channels SET linkedSourceId=?, source=? WHERE id=?",
            (primary[0] if primary else None, primary[1] if primary else "", cid),
        )

    # ---- commands ----
    def cmd_list(self):
        print(f"database: {self.path}\n")
        print("== owned channels ==")
        for cid, name, handle, cached in self.cur.execute(
            "SELECT id, name, handle, linkedSourceId FROM my_channels ORDER BY name"
        ):
            srcs = self.sources_for_channel(cid)
            src_txt = ", ".join(f"{s[1]} ({s[0]})" for s in srcs) or "(none)"
            print(f"  {name} [{handle}] id={cid}\n      sources: {src_txt}")
        print("\n== source channels ==")
        for sid, handle, owner in self.cur.execute(
            "SELECT id, handle, linkedMyChannelId FROM source_channels ORDER BY handle"
        ):
            who = self.cur.execute(
                "SELECT name FROM my_channels WHERE id=?", (owner,)
            ).fetchone() if owner else None
            print(f"  {handle or sid} ({sid}) -> {who[0] if who else 'UNASSIGNED'}")
        print("\n== conflicts (edge vs cache disagree) ==")
        bad = []
        for sid, handle, owner in self.cur.execute(
            "SELECT id, handle, linkedMyChannelId FROM source_channels"
        ):
            for cid, cached in self.cur.execute(
                "SELECT id, linkedSourceId FROM my_channels WHERE linkedSourceId=?", (sid,)
            ):
                if owner != cid and owner is not None:
                    bad.append((handle, sid, cid))
        print("\n".join(f"  {h} ({s}) cache says {c}, edge says another owner" for h, s, c in bad) or "  none")

    def cmd_link(self, sid, cid, duplicate, new_id, apply):
        src = self.source(sid)
        if not src:
            sys.exit(f"error: unknown source id {sid} (run 'list' for ids)")
        ch = self.my_channel(cid)
        if not ch:
            sys.exit(f"error: unknown channel id {cid} (run 'list' for ids)")
        owner = src[6]
        if not duplicate and owner and owner != cid:
            other = self.my_channel(owner)
            print(f"plan: MOVE {src[2]} from {other[1] if other else owner} to {ch[1]}")
        elif duplicate:
            if owner == cid:
                sys.exit("error: source already belongs to this channel; --duplicate is for a SECOND channel")
            if owner is None:
                sys.exit("error: source is unowned; plain link (no --duplicate) is enough")
            existing = self.cur.execute(
                "SELECT id FROM source_channels WHERE url=? AND linkedMyChannelId=?", (src[1], cid)
            ).fetchone()
            if existing:
                sys.exit(f"error: channel already has a source row for this URL ({existing[0]})")
            new_id = new_id or f"{sid}-dd"
            if self.source(new_id):
                sys.exit(f"error: new row id {new_id} already exists")
            print(f"plan: DUPLICATE {src[2]} as {new_id} -> {ch[1]} (original stays with its owner)")
            if not apply:
                return self._dry()
            self.cur.execute("BEGIN")
            self.cur.execute(
                "INSERT INTO source_channels "
                "(id,url,handle,name,nicheId,avatar,lastScrapedAt,lastVisitedAt,"
                "lastSeenVideoId,linkedMyChannelId,videoCount) "
                "SELECT ?,url,handle,name,nicheId,avatar,?,?,?,?,videoCount FROM source_channels WHERE id=?",
                (new_id, now_iso(), now_iso(), None, cid, sid),
            )
            self.cur.execute(
                "UPDATE my_channels SET linkedSourceId=?, source=? WHERE id=?", (new_id, src[2], cid)
            )
            self.con.commit()
            return self._after([sid, new_id], [cid])
        else:
            print(f"plan: LINK {src[2]} -> {ch[1]}")
        if not apply:
            return self._dry()
        self.cur.execute("BEGIN")
        self.write_owner(sid, cid)
        self.con.commit()
        self._after([sid], [cid])

    def cmd_unlink(self, sid, apply):
        src = self.source(sid)
        if not src:
            sys.exit(f"error: unknown source id {sid}")
        if src[6] is None:
            sys.exit("error: source is not linked to any channel")
        print(f"plan: UNLINK {src[2]} from its channel")
        if not apply:
            return self._dry()
        self.cur.execute("BEGIN")
        self.write_owner(sid, None)
        self.con.commit()
        self._after([sid], [src[6]])

    def _dry(self):
        print("dry-run: no changes written (pass --apply to write)")

    def _after(self, sids, cids):
        print("after:")
        for s in sids:
            print("  src", self.source(s))
        for c in cids:
            print("  my ", self.my_channel(c))


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    sub = ap.add_subparsers(dest="cmd", required=True)
    p = sub.add_parser("list")
    p.add_argument("--db")
    p = sub.add_parser("link")
    p.add_argument("--source", required=True)
    p.add_argument("--channel", required=True)
    p.add_argument("--duplicate", action="store_true", help="second row for the same YouTube channel")
    p.add_argument("--new-id")
    p.add_argument("--db")
    p.add_argument("--apply", action="store_true")
    p = sub.add_parser("unlink")
    p.add_argument("--source", required=True)
    p.add_argument("--db")
    p.add_argument("--apply", action="store_true")
    a = ap.parse_args()

    m = Mapping(find_db(a.db))
    if a.cmd == "list":
        m.cmd_list()
    elif a.cmd == "link":
        m.cmd_link(a.source, a.channel, a.duplicate, a.new_id, a.apply)
    elif a.cmd == "unlink":
        m.cmd_unlink(a.source, a.apply)


if __name__ == "__main__":
