def scrape(ytdlp, url):
    """Return (entries, channel_meta, None) or ([], None, error)."""
    try:
        r = subprocess.run(
            [str(ytdlp), "--flat-playlist", "-J", "--no-warnings", url],
            capture_output=True, timeout=300,
        )
    except subprocess.TimeoutExpired:
        return [], None, "timeout after 300s"
    if r.returncode != 0:
        first = (r.stderr or b"").decode("utf-8", "replace").strip().splitlines()
        return [], None, first[-1][:200] if first else f"exit {r.returncode}"
    try:
        data = json.loads(r.stdout.decode("utf-8", "replace"))
    except json.JSONDecodeError as e:
        return [], None, f"bad JSON: {e}"
    entries = data.get("entries") or []
    return entries, data, None

