// Compute per-channel "today's video suggestion" from a scrape workdir produced by
// scrape_channels.py, using the app's OWN matcher (shared/match.ts) bundled fresh with the
// repo's esbuild — never a reimplementation, so thresholds can't diverge from the app.
//
//   node compute_suggestions.mjs --workdir <dir> [--repo <repo-root>] [--out <file>]
//
// A source video is "covered" when matchUploads matches it (>= 0.6 floor) against the
// uploads of ANY owned channel. Suggestion = newest uncovered video (a flat /videos dump
// is newest-first, so playlist rank is recency), plus a most-viewed alternative.

import { spawnSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'
import os from 'node:os'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))

function arg(name, dflt) {
  const i = process.argv.indexOf(`--${name}`)
  return i >= 0 ? process.argv[i + 1] : dflt
}

const workdir = arg('workdir')
if (!workdir) { console.error('error: --workdir is required'); process.exit(1) }
const repo = arg('repo', path.resolve(__dirname, '..', '..', '..', '..'))
const out = arg('out', path.join(workdir, 'suggestions.json'))

// 1. Bundle the app's matcher fresh (guards against edits to shared/match.ts).
const esbuildBin = path.join(repo, 'node_modules', 'esbuild', 'bin', 'esbuild')
const matchTs = path.join(repo, 'shared', 'match.ts')
if (!fs.existsSync(esbuildBin)) { console.error(`error: esbuild not found at ${esbuildBin} (npm install)`); process.exit(1) }
if (!fs.existsSync(matchTs)) { console.error(`error: app matcher not found at ${matchTs}`); process.exit(1) }
const bundle = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'mes-match-')), 'match.mjs')
const b = spawnSync(process.execPath, [esbuildBin, matchTs, '--bundle', '--format=esm', `--outfile=${bundle}`], { encoding: 'utf8' })
if (b.status !== 0) { console.error('error: esbuild failed:\n' + b.stderr); process.exit(1) }
const { matchUploads } = await import(pathToFileUrl(bundle))

const manifest = JSON.parse(fs.readFileSync(path.join(workdir, 'manifest.json'), 'utf8'))
const loadEntries = (file) => {
  if (!file) return []
  const d = JSON.parse(fs.readFileSync(path.join(workdir, file), 'utf8'))
  return (d.entries || []).map((e, rank) => ({
    id: e.id, title: e.title || '', views: e.view_count ?? null,
    duration: e.duration ?? null, rank,
    url: `https://www.youtube.com/watch?v=${e.id}`,
  }))
}

// 2. Uploads from ALL owned channels — a video live on any channel is covered.
const uploads = []
for (const ch of manifest.owned) {
  for (const e of loadEntries(ch.file)) {
    uploads.push({ channelId: ch.id, title: e.title })
  }
}

// 3. Per channel: match its sources' videos, keep the uncovered ones.
const report = {}
for (const ch of manifest.owned) {
  const byVideoId = new Map()
  for (const src of ch.sources || []) {
    for (const e of loadEntries(src.file)) {
      if (!byVideoId.has(e.id)) byVideoId.set(e.id, { ...e, sourceHandle: src.handle })
    }
  }
  const items = [...byVideoId.values()]
  const matches = new Map(matchUploads(
    items.map((e) => ({ videoId: e.id, title: e.title })), uploads
  ).map((m) => [m.videoId, m]))
  const uncovered = items
    .map((e) => {
      const m = matches.get(e.id)
      return { ...e, covered: m ? m.uploadedTo : null, score: m ? m.score : null, confidence: m ? m.confidence : null }
    })
    .filter((e) => !e.covered)
    .sort((x, y) => x.rank - y.rank || (y.views || 0) - (x.views || 0))
  const dead = (ch.sources || []).filter((s) => s.error).map((s) => ({ handle: s.handle, error: s.error }))
  report[ch.name] = {
    channelId: ch.id,
    myUploads: loadEntries(ch.file).length,
    scrapeError: ch.error || null,
    deadSources: dead,
    sourceVideos: items.length,
    coveredCount: items.length - uncovered.length,
    uncoveredCount: uncovered.length,
    suggestion: uncovered[0] || null,
    popularAlternative: uncovered.length
      ? uncovered.slice(0, 30).reduce((acc, e) => ((e.views || 0) > (acc.views || 0) ? e : acc))
      : null,
    next: uncovered.slice(1, 6),
  }
}

fs.writeFileSync(out, JSON.stringify(report, null, 2), 'utf8')

// 4. Human-readable summary.
for (const [name, r] of Object.entries(report)) {
  console.log(`\n${name}  (${r.myUploads} uploads, ${r.sourceVideos} source videos, ${r.coveredCount} covered)`)
  if (r.scrapeError) console.log(`  !! channel scrape failed: ${r.scrapeError}`)
  for (const d of r.deadSources) console.log(`  !! source ${d.handle}: ${d.error}`)
  if (!r.sourceVideos) { console.log('  (no linked source — nothing to suggest)'); continue }
  if (r.suggestion) {
    console.log(`  suggest: ${r.suggestion.title}`)
    console.log(`           ${r.suggestion.url}  [${fmtViews(r.suggestion.views)} views, ${fmtDur(r.suggestion.duration)}]`)
  } else {
    console.log('  (every source video is already covered)')
  }
  if (r.popularAlternative && r.popularAlternative !== r.suggestion) {
    console.log(`  popular: ${r.popularAlternative.title} [${fmtViews(r.popularAlternative.views)} views]`)
  }
}
console.log(`\nwrote ${out}`)

function fmtViews(v) { return v == null ? '?' : v >= 1000 ? `${Math.round(v / 1000)}K` : String(v) }
function fmtDur(s) { return s == null ? '?' : `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}` }
function pathToFileUrl(p) { return 'file://' + p.replace(/\\/g, '/') }

